//! Tests comparing the buffer port with JTS. The `tests/resources/buffer/*.txt.gz` files are generated by running JTS
//! (the planetiler-dist jar) on each input: `CASE <distance bits> <input WKB>`, then one `CURVE <left is interior>
//! <n> <x bits> <y bits>...` line per raw offset curve from `BufferCurveSetBuilder`, then `RESULT <WKB>` with the
//! output of `BufferOp(input, mitre params).getResultGeometry(distance)`.

use std::path::PathBuf;

use geo::Area;
use geo_types::{Coord, Geometry};

use super::*;
use crate::geo::geo_utils::read_wkb;
use crate::geo::normalize::norm;
use crate::geo::wkt::read_wkt;

fn resource(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/resources/buffer").join(name)
}

struct Case {
    distance: f64,
    input: Geometry<f64>,
    curves: Vec<Vec<Coord<f64>>>,
    result: Geometry<f64>,
}

fn hex_bytes(hex: &str) -> Vec<u8> {
    (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect()
}

fn bits(hex: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(hex, 16).unwrap())
}

fn read_cases(name: &str) -> Vec<Case> {
    let data = crate::util::gzip::gunzip(&std::fs::read(resource(name)).unwrap()).unwrap();
    let text = String::from_utf8(data).unwrap();
    let mut cases: Vec<Case> = Vec::new();
    for line in text.lines() {
        let mut parts = line.split(' ');
        match parts.next().unwrap() {
            "CASE" => {
                let distance = bits(parts.next().unwrap());
                let input = read_wkb(&hex_bytes(parts.next().unwrap())).unwrap();
                cases.push(Case {
                    distance,
                    input,
                    curves: vec![],
                    result: Geometry::GeometryCollection(Default::default()),
                });
            }
            "CURVE" => {
                let left_interior = parts.next().unwrap() == "1";
                let n: usize = parts.next().unwrap().parse().unwrap();
                let mut coords: Vec<Coord<f64>> =
                    (0..n).map(|_| Coord { x: bits(parts.next().unwrap()), y: bits(parts.next().unwrap()) }).collect();
                if !left_interior {
                    coords.reverse();
                }
                cases.last_mut().unwrap().curves.push(coords);
            }
            "RESULT" => cases.last_mut().unwrap().result = read_wkb(&hex_bytes(parts.next().unwrap())).unwrap(),
            other => panic!("unexpected line {other}"),
        }
    }
    cases
}

fn coords_of(geom: &Geometry<f64>) -> Vec<Vec<Coord<f64>>> {
    crate::geo::polygon_overlay::polygons_of(geom)
        .into_iter()
        .flat_map(|p| std::iter::once(p.exterior()).chain(p.interiors()))
        .map(|r| r.0.clone())
        .collect()
}

/// Removes vertices within `tolerance` of the previous one (and the closing point if it is within `tolerance` of the
/// start).
fn dedupe(ring: Vec<Coord<f64>>, tolerance: f64) -> Vec<Coord<f64>> {
    let near = |a: &Coord<f64>, b: &Coord<f64>| (a.x - b.x).abs() <= tolerance && (a.y - b.y).abs() <= tolerance;
    let mut out: Vec<Coord<f64>> = Vec::with_capacity(ring.len());
    for c in ring {
        if !out.last().is_some_and(|l| near(l, &c)) {
            out.push(c);
        }
    }
    while out.len() > 1 && near(&out[0], out.last().unwrap()) {
        out.pop();
    }
    out
}

/// Rings with near-duplicate vertices removed, as a geometry that can be normalized.
fn deduped(geom: &Geometry<f64>, tolerance: f64) -> Geometry<f64> {
    let ring = |r: &geo_types::LineString<f64>| geo_types::LineString::from(dedupe(r.0.clone(), tolerance));
    let polys = crate::geo::polygon_overlay::polygons_of(geom)
        .into_iter()
        .map(|p| geo_types::Polygon::new(ring(p.exterior()), p.interiors().iter().map(ring).collect()))
        .collect();
    crate::geo::polygon_overlay::to_polygonal(polys)
}

/// Whether two buffer results have the same rings (after normalization) with vertices within `tolerance`. JTS
/// computes the intersection points between curves in floating point and `i_overlay` on an integer grid, so where
/// several curves cross within a few ulps JTS can emit a cluster of nearly identical vertices where the port emits
/// fewer; those clusters are merged first.
fn same_result(expected: &Geometry<f64>, actual: &Geometry<f64>, tolerance: f64) -> bool {
    let (e, a) = (coords_of(&norm(&deduped(expected, tolerance))), coords_of(&norm(&deduped(actual, tolerance))));
    e.len() == a.len()
        && e.iter().zip(&a).all(|(e, a)| {
            e.len() == a.len()
                && e.iter().zip(a).all(|(e, a)| (e.x - a.x).abs() <= tolerance && (e.y - a.y).abs() <= tolerance)
        })
}

/// Whether two curve sets have the same structure with every coordinate within a few ulps.
fn curves_within_ulps(expected: &[Vec<Coord<f64>>], actual: &[Vec<Coord<f64>>]) -> bool {
    let close = |a: f64, b: f64| (a - b).abs() <= 4.0 * f64::EPSILON * a.abs().max(b.abs()).max(1.0);
    expected.len() == actual.len()
        && expected
            .iter()
            .zip(actual)
            .all(|(e, a)| e.len() == a.len() && e.iter().zip(a).all(|(e, a)| close(e.x, a.x) && close(e.y, a.y)))
}

/// Area of the symmetric difference between two polygonal geometries.
fn symmetric_difference_area(a: &Geometry<f64>, b: &Geometry<f64>) -> f64 {
    let d1 = crate::geo::polygon_overlay::difference(a, b).unwrap().unsigned_area();
    let d2 = crate::geo::polygon_overlay::difference(b, a).unwrap().unsigned_area();
    d1 + d2
}

/// Compares the port with JTS on every case in `name`:
///
/// - The raw offset curves must be bit-for-bit identical, except that up to `max_ulp_curves` cases may differ by a
///   few ulps: limited mitre joins (and round joins/caps) use `sin`/`cos`, and Java's `Math.sin`/`Math.cos`
///   intrinsics are not always correctly rounded the same way as fdlibm (`StrictMath`, which the port uses).
/// - The buffer results must have the same vertices (within 1e-9, after merging clusters of near-identical vertices),
///   except that up to `max_near_results` cases may differ by less than 1e-6 px² (plus 1e-9 of the area) in area. Those are big unions where
///   curves cross within a few ulps of each other and JTS's floating point intersection points (computed with
///   ill-conditioned nearly-parallel segments) are up to ~1e-8 off from the exact ones `i_overlay` computes on its
///   integer grid, which can also turn a 1e-13 wide neck into two polygons touching at a point. All of these vanish
///   when the output is rounded to the 1/16 px tile grid.
fn check_cases(name: &str, max_ulp_curves: usize, max_near_results: usize) {
    let cases = read_cases(name);
    assert!(!cases.is_empty());
    let mut curve_failures = Vec::new();
    let mut ulp_curves = 0;
    let mut result_failures = Vec::new();
    let mut near_results = 0;
    for (i, case) in cases.iter().enumerate() {
        let curves =
            curve_set_builder::CurveSetBuilder::new(case.distance, BufferParameters::mitre()).curves(&case.input);
        if curves != case.curves {
            if curves_within_ulps(&case.curves, &curves) {
                ulp_curves += 1;
            } else {
                let detail = if curves.len() != case.curves.len() {
                    format!("{} curves, expected {}", curves.len(), case.curves.len())
                } else {
                    let (j, (e, a)) = case.curves.iter().zip(&curves).enumerate().find(|(_, (e, a))| e != a).unwrap();
                    let k = e.iter().zip(a).position(|(e, a)| e != a).unwrap_or(e.len().min(a.len()));
                    format!(
                        "curve {j} (len {} vs {}) differs at {k}: expected {:?} actual {:?}",
                        e.len(),
                        a.len(),
                        &e[k.saturating_sub(2)..(k + 3).min(e.len())],
                        &a[k.saturating_sub(2)..(k + 3).min(a.len())]
                    )
                };
                curve_failures.push(format!("case {i} buffer({}) of {:?}: {detail}", case.distance, case.input));
            }
        }
        let result = buffer(&case.input, case.distance, &BufferParameters::mitre()).unwrap();
        if !same_result(&case.result, &result, 1e-9) {
            let diff = symmetric_difference_area(&case.result, &result);
            if diff < 1e-6 + 1e-9 * case.result.unsigned_area() {
                near_results += 1;
            } else {
                result_failures.push(format!(
                    "case {i} buffer({}) of {:?}:\n  expected {:?}\n  actual   {:?}\n  area {} vs {}, difference {diff}",
                    case.distance,
                    case.input,
                    norm(&case.result),
                    norm(&result),
                    case.result.unsigned_area(),
                    result.unsigned_area()
                ));
            }
        }
    }
    eprintln!(
        "{name}: {} cases, {ulp_curves} with curves differing by a few ulps, {near_results} with results within 1e-6 px²",
        cases.len()
    );
    assert!(
        curve_failures.is_empty()
            && result_failures.is_empty()
            && ulp_curves <= max_ulp_curves
            && near_results <= max_near_results,
        "{} of {} cases: {} curve differences, {ulp_curves} ulp curve differences, {} result differences, {near_results} near results\n{}\n{}",
        name,
        cases.len(),
        curve_failures.len(),
        result_failures.len(),
        curve_failures.iter().take(3).cloned().collect::<Vec<_>>().join("\n"),
        result_failures.iter().take(3).cloned().collect::<Vec<_>>().join("\n"),
    );
}

#[test]
fn buffer_square() {
    let geom = read_wkt("POLYGON ((0 0, 10 0, 10 10, 0 10, 0 0))").unwrap();
    let out = buffer(&geom, 1.0, &BufferParameters::mitre()).unwrap();
    assert!((out.unsigned_area() - 144.0).abs() < 1e-9, "{out:?}");
    let out = buffer(&geom, -1.0, &BufferParameters::mitre()).unwrap();
    assert!((out.unsigned_area() - 64.0).abs() < 1e-9, "{out:?}");
    let out = buffer(&geom, -6.0, &BufferParameters::mitre()).unwrap();
    assert_eq!(0.0, out.unsigned_area());
}

/// Synthetic cases: mitre/limited mitre/bevel joins, inside turns with closing segments, input simplification,
/// collinear vertices, eroded rings and triangles, holes, overlapping multipolygons, lines and points.
#[test]
fn buffer_matches_jts_synthetic_cases() {
    check_cases("cases.txt.gz", 5, 0);
}

/// `+0.5`/`-0.5` buffers of the first 400 buildings of a Boston z13 tile, and the `-0.5` unbuffer of 100 unions of
/// buffered nearby buildings (the `FeatureMerge.bufferUnionUnbuffer` inputs).
#[test]
fn buffer_matches_jts_boston_tile() {
    check_cases("tile_boston_13_2477_3028.txt.gz", 0, 1);
}

/// Same as [`buffer_matches_jts_boston_tile`] for a Jakarta z13 tile.
#[test]
fn buffer_matches_jts_jakarta_tile() {
    check_cases("tile_jakarta_13_6527_4240.txt.gz", 5, 2);
}
